"""Black Friday Short: beats, asset bindings, manifest (production.json), short_spec.json. Beat starts come from voice/beats.json (Whisper word timings of the approved Qwen narration).
  project/.tools/venv/bin/python production/black-friday-30s/short_spec.py
"""
import hashlib, json
from pathlib import Path
HERE = Path(__file__).resolve().parent; ROOT = HERE.parents[1]; FPS = 24; DISCLAIMER = "Educational content only, not financial advice."
B = [  # id, kind, composition, action, purpose, assets
 ("hook", "presenter", "ren-left-shop-street", "Ren (genuine clip, pointing at camera) in front of the shop; BLACK FRIDAY plaque drops in; TEST stamp lands", "Introduce the premise", ["ren_point_camera", "E1"]),
 ("countdown", "graphic", "phone-countdown-closeup", "Phone on the table: countdown ticks, ONLY 3 LEFT and RUSH badges pop", "Show the pressure tactics", ["E2"]),
 ("rule-one", "presenter", "ren-left-notepad", "Ren with the clipboard clip; notepad lists three items typed in; RULE 1 tag", "Rule one: a list", ["ren_clipboard_tick", "E2"]),
 ("not-listed", "graphic", "notepad-closeup-cross", "Notepad close-up: an unlisted item is typed and crossed out", "Not on the list, not a deal", ["E2"]),
 ("rule-two", "presenter", "ren-left-calculator", "Ren points down-right at a calculator; RULE 2 tag", "Rule two: do the math", ["ren_point_down_right", "E2"]),
 ("the-math", "graphic", "calculator-closeup-price", "Calculator: $100 x 0.70 = $70; the $100 tag is struck and becomes $70", "Show the maths", ["E2"]),
 ("savings", "presenter", "ren-left-parcels", "Ren shrugs beside a pile of parcels; 'only savings if you needed it' card", "Savings need need", ["ren_shrug", "E3"]),
 ("rule-three", "action", "hourglass-cart", "Hourglass flips; cart phone shows 24h; RULE 3 tag", "Rule three: wait 24 hours", ["P2", "E2"]),
 ("tomorrow", "presenter", "ren-left-morning", "Ren nods; 'Still want it tomorrow?' then BUY IT tick", "Decision after the wait", ["ren_nod_yes", "E4"]),
 ("cta", "presenter", "ren-left-end-card", "Ren thumbs up; piggy bank; workbook end card; closing disclaimer held 2 s+", "Call to action", ["ren_thumbs_up", "P1", "E4"]),
]
def lib(n): return f"assets/ren_library/{n}.mp4"
def bf(n): return f"production/black-friday-30s/assets/black-friday/{n}.png"
EVID_ENV = "Generated with FLUX.2-dev (pack manifest, 14 Nov 2026), TEMPORARY. Owner replied 'Approved' (14 Nov 2026) to the asset report that listed it as a placeholder, so it is used as a placeholder for the prototype; final art approval is NOT given and is requested at the prototype gate"
ASSETS = [
 ("script", "script", "production/black-friday-30s/script/ren-black-friday-30s.md", "Owner script, approved in chat ('Approved', 14 Nov 2026) in reply to the asset report"),
 ("audio", "audio", "production/black-friday-30s/voice/narration.wav", "Qwen British Ren clone generated from the approved script after approval (voice/timings.json)"),
 ("renderer", "renderer", "production/black-friday-30s/render_short.py", "Portrait renderer under the Shorts launcher; reuses pilot_ren.RenClip matting and the Three Bills/401(k) Short layout code"),
 ("configuration", "configuration", "production/black-friday-30s/short_spec.json", "Generated by short_spec.py from voice/beats.json"),
 ("ren_point_camera", "character", lib("ren_point_camera"), "Approved Ren library clip (library.json, status ok)"),
 ("ren_clipboard_tick", "character", lib("ren_clipboard_tick"), "Approved Ren library clip (library.json, status ok)"),
 ("ren_point_down_right", "character", lib("ren_point_down_right"), "Approved Ren library clip (library.json, status ok)"),
 ("ren_shrug", "character", lib("ren_shrug"), "Approved Ren library clip (library.json, status ok)"),
 ("ren_nod_yes", "character", lib("ren_nod_yes"), "Approved Ren library clip (library.json, status ok)"),
 ("ren_thumbs_up", "character", lib("ren_thumbs_up"), "Approved Ren library clip (library.json, status ok)"),
 ("E1", "environment", bf("E1_shop_street"), EVID_ENV), ("E2", "environment", bf("E2_kitchen_table"), EVID_ENV), ("E3", "environment", bf("E3_porch_parcels"), EVID_ENV), ("E4", "environment", bf("E4_living_room_morning"), EVID_ENV),
 ("P1", "prop", bf("P1_piggy_bank"), EVID_ENV), ("P2", "prop", bf("P2_hourglass"), EVID_ENV),
 ("typography", "font", "project/remotion/public/fonts/fredoka-latin-700-normal.woff2", "Fredoka, the established house typeface"),
]
def sha(p): return hashlib.sha256((ROOT / p).read_bytes()).hexdigest()
def main():
    t = json.loads((HERE / "voice" / "timings.json").read_text()); beats = json.loads((HERE / "voice" / "beats.json").read_text()); nf = int(-(-t["duration"] * FPS // 1))
    starts = [0.0] + [max(0.0, b["start"] - 0.12) for b in beats[1:]]; frames = [round(s * FPS) for s in starts] + [nf]; spec = {"fps": FPS, "frames": nf, "disclaimer": DISCLAIMER, "narration_s": t["duration"], "beats": []}; scenes = []
    for i, (sid, kind, comp, action, purpose, assets) in enumerate(B):
        fa, fb = frames[i], frames[i + 1]; d = (fb - fa) / FPS; assert fb > fa
        spec["beats"].append(dict(id=sid, start_frame=fa, end_frame=fb, kind=kind, composition=comp, narration=beats[i]["text"]))
        s = dict(id=sid, start_frame=fa, end_frame=fb, kind=kind, composition=comp, action=action, motion_purpose=purpose, assets=assets, animations=[sid + "-motion"], environment_fullscreen=True)
        if d < 2 or d > {'presenter': 5.5, 'graphic': 3.5}.get(kind, 4.0): s["timing_justification"] = f"Beat length {d:.1f} s follows the spoken line boundaries; the visual change lands on its words"
        scenes.append(s)
    (HERE / "short_spec.json").write_text(json.dumps(spec, indent=1))
    man = {"schema_version": 1, "title": "Ren | Black Friday test: 30-second Short", "width": 1080, "height": 1920, "fps": FPS, "frames": nf, "full_bleed": True, "permanent_border": False, "asset_report": "ASSET_REQUIREMENTS.md",
           "layout_evidence": "layout.json", "prototype": "prototype.mp4", "prototype_report": "prototype.qa.json",
           "assets": [dict(id=i, kind=k, path=str(Path("../..") / p), sha256=sha(p), status="approved", approval_evidence=e) for i, k, p, e in ASSETS], "scenes": scenes}
    groups = [dict(start=b["start"], end=b["end"], text=b["text"]) for b in beats]; man["audio_cues"] = groups; (HERE / "production.json").write_text(json.dumps(man, indent=1, ensure_ascii=False))
    print(len(scenes), "beats,", nf, "frames,", t["duration"], "s")
    for s in scenes: d = (s["end_frame"] - s["start_frame"]) / FPS; print(f"  {s['id']:12s} {s['start_frame'] / FPS:6.2f}-{s['end_frame'] / FPS:6.2f} {d:4.2f}s {s['kind']:10s}{'  (justified)' if s.get('timing_justification') else ''}")
if __name__ == "__main__": main()
